50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	export const runScenario = (scenario: Scenario): ScenarioOutput => {
58	  return { results: scenario.steps.map(() => ({ premium: PROCESSING_FEE })) };
59	};
