1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest case ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Quote: single main items, base premium + first insurance + fee ---
16	  it.todo("single sword (base 100 G) → premium 115 G (100 + 10 first insurance + 5 fee)");
17	  it.todo("single amulet (base 60 G) → premium 71 G (60 + 6 first insurance + 5 fee)");
18	  it.todo("single staff (base 80 G) → premium 93 G (80 + 8 first insurance + 5 fee)");
19	  it.todo("single potion (base 40 G) → premium 49 G (40 + 4 first insurance + 5 fee)");
20	
21	  // --- Components and building blocks ---
22	  it.todo("1 rune → base premium 25 G");
23	  it.todo("2 runes → base premium 50 G");
24	  it.todo("3 runes → base premium 60 G (block of 3 alike applies)");
25	  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
26	  it.todo("7 runes → base premium 175 G (no block for 7)");
27	  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
28	  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");
29	
30	  // --- Item-specific modifiers ---
31	  it.todo("cursed sword adds 50 % of the sword's base premium (50 G surcharge)");
32	  it.todo("sword with enchantment exactly 5 → 30 % high-enchantment surcharge applies");
33	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
34	  it.todo("cursed sword with enchantment exactly 5 → both surcharges apply");
35	
36	  // --- Modifier scope on multi-item policies ---
37	  it.todo(
38	    "cursed sword + plain amulet → curse surcharge is 50 G (50 % of the cursed item only), policy base 210 G before further modifiers and fee",
39	  );
40	
41	  // --- Policy-wide modifiers ---
42	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
43	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
44	  it.todo("second quote in the scenario → 15 % follow-up contract discount applies");
45	  it.todo("first insurance surcharge applies to every item, even on a follow-up contract");
46	
47	  // --- Rounding ---
48	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
49	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
50	
51	  // --- Quote errors ---
52	  it.todo("quote with an unknown item type (broomstick) → error, no results");
53	
54	  // --- Claims: standard reimbursement ---
55	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
56	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
57	  it.todo("damage below the deductible → payout 0 G");
58	
59	  // --- Claims: special clauses ---
60	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
61	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
62	  it.todo("dragon-material sword, enchantment exactly 8, damage 1000 G → payout 400 G (50 % rule applies, then deductible)");
63	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
64	
65	  // --- Claims: deductible per damage event ---
66	  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
67	
68	  // --- Claims: cap ---
69	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
70	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
71	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not affect the insurance sum)");
72	  it.todo("cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
73	  it.todo("sword insured, two claims of 1500 G: first → payout 1400 G, remaining cap 600 G");
74	  it.todo("sword insured, two claims of 1500 G: second → payout 600 G, remaining cap 0 G");
75	
76	  // --- Claims: multiple items of the same type ---
77	  it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
78	  it.todo("more damage entries of a type than insured items → error, whole claim rejected");
79	
80	  // --- Claims: rounding ---
81	  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
82	
83	  // --- Claim errors ---
84	  it.todo("claim damaging an amulet when only a sword is insured → error");
85	  it.todo("claim damaging an item with an unknown type → error");
86	  it.todo("claim with a damage entry of amount -200 → error");
87	
88	  // --- Integration examples ---
89	  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
90	  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
91	
92	  // --- CLI ---
93	  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout");
94	  it.todo("CLI exits with a non-zero status and writes an error to stderr on an invalid scenario");
95	});
